export function enrichProductDescription(accessory) {
  if (accessory.description?.includes("\n\nFeatures")) {
    return accessory.description;
  }

  const details = descriptionSections[accessory.category] ?? descriptionSections.earrings;
  const intro =
    accessory.description ??
    `${accessory.name} is an AR try-on compatible accessory designed to help you preview its shape, style, and fit before purchase.`;
  const categoryName =
    accessory.category === "sunglasses"
      ? "Sunglasses"
      : accessory.category === "necklace"
        ? "Necklace"
        : "Earrings";
  const placementName =
    accessory.placement === "eyes"
      ? "Eyes"
      : accessory.placement === "neck"
        ? "Neck"
        : "Ears";
  const price = accessory.price ? `\nPrice: NPR ${accessory.price}` : "";

  return `${intro}\n\nUse AuraAR's virtual try-on feature to see how ${accessory.name} looks on you before making your purchase. Designed for confident styling, this piece helps you compare fit, shape, and overall look directly from your screen.\n\nFeatures\n${details.features.join("\n")}\n\nSpecifications\n${details.specifications.join("\n")}\nProduct Name: ${accessory.name}${price}\nAR Placement: ${placementName}\nProduct Type: ${categoryName}\n\nCare Instructions\n${details.care.join("\n")}`;
}

