export const accessories = accessoryItems.map((accessory) => ({
  ...accessory,
  description: enrichProductDescription(accessory)
}));

export function getAccessoryById(accessoryId) {
  return accessories.find((item) => item.id === accessoryId) ?? accessories[0];
}
